    {id:'again', job:'build', attempt:2, seq:8, type:'started'},
    {id:'start', job:'build', attempt:1, seq:2, type:'started'},
  ])), {jobs:[{job:'build', attempts:[
    {attempt:1,status:'succeeded',startedSeq:2,finishedSeq:9},
