import { readFileSync } from 'node:fs';

function isPositiveSafeInteger(value) {
  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0;
}

function isNonNegativeSafeInteger(value) {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function parseEvent(line) {
  let obj;
  try {
    obj = JSON.parse(line);
  } catch {
    throw new Error(`Invalid JSON: ${line}`);
  }
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    throw new Error(`Event must be a non-null non-array object: ${line}`);
  }
  const { id, job, attempt, seq, type } = obj;
  if (!isNonEmptyString(id)) throw new Error(`Invalid id: ${line}`);
  if (!isNonEmptyString(job)) throw new Error(`Invalid job: ${line}`);
  if (!isPositiveSafeInteger(attempt)) throw new Error(`Invalid attempt: ${line}`);
  if (!isNonNegativeSafeInteger(seq)) throw new Error(`Invalid seq: ${line}`);
  if (type !== 'started' && type !== 'succeeded' && type !== 'failed') {
    throw new Error(`Invalid type: ${line}`);
  }
  return { id, job, attempt, seq, type };
}

function sameEvent(a, b) {
  return (
    a.id === b.id &&
    a.job === b.job &&
    a.attempt === b.attempt &&
    a.seq === b.seq &&
    a.type === b.type
  );
}

export function reduceEvents(text) {
  const lines = text.split(/\r\n|\n/).filter(line => line.trim().length > 0);

  const byId = new Map();
  let duplicates = 0;

  for (const line of lines) {
    const event = parseEvent(line);
    const existing = byId.get(event.id);
    if (existing === undefined) {
      byId.set(event.id, event);
    } else if (sameEvent(existing, event)) {
      duplicates += 1;
    } else {
      throw new Error(`Conflicting event for id ${event.id}`);
    }
  }

  const jobsMap = new Map();

  for (const event of byId.values()) {
    let attempts = jobsMap.get(event.job);
    if (attempts === undefined) {
      attempts = new Map();
      jobsMap.set(event.job, attempts);
    }
    let record = attempts.get(event.attempt);
    if (record === undefined) {
      record = { started: null, terminal: null };
      attempts.set(event.attempt, record);
    }
    if (event.type === 'started') {
      if (record.started !== null && record.started.id !== event.id) {
        throw new Error(
          `Repeated start with different id for job ${event.job} attempt ${event.attempt}`
        );
      }
      record.started = event;
    } else {
      if (record.terminal !== null) {
        if (record.terminal.id !== event.id || record.terminal.type !== event.type) {
          throw new Error(
            `Contradictory terminal for job ${event.job} attempt ${event.attempt}`
          );
        }
      }
      record.terminal = event;
    }
  }

  const jobs = [];
  const sortedJobNames = [...jobsMap.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

  for (const jobName of sortedJobNames) {
    const attemptsMap = jobsMap.get(jobName);
    const sortedAttemptNumbers = [...attemptsMap.keys()].sort((a, b) => a - b);
    const attempts = [];
    for (const attemptNumber of sortedAttemptNumbers) {
      const record = attemptsMap.get(attemptNumber);
      if (record.started === null) {
        throw new Error(`Orphan terminal for job ${jobName} attempt ${attemptNumber}`);
      }
      if (record.terminal !== null && record.terminal.seq <= record.started.seq) {
        throw new Error(
          `Terminal seq must be strictly greater than started seq for job ${jobName} attempt ${attemptNumber}`
        );
      }
      attempts.push({
        attempt: attemptNumber,
        status: record.terminal === null ? 'running' : record.terminal.type,
        startedSeq: record.started.seq,
        finishedSeq: record.terminal === null ? null : record.terminal.seq,
      });
    }
    jobs.push({ job: jobName, attempts });
  }

  return { jobs, duplicates };
}

function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('Usage: receipt-report.js LOGFILE\n');
    process.exit(2);
  }
  let text;
  try {
    text = readFileSync(args[0], 'utf8');
  } catch (err) {
    process.stderr.write(`Failed to read file: ${err.message}\n`);
    process.exit(2);
  }
  try {
    const report = reduceEvents(text);
    process.stdout.write(JSON.stringify(report) + '\n');
    process.exit(0);
  } catch (err) {
    process.stderr.write(`${err.message}\n`);
    process.exit(2);
  }
}

const isMain = process.argv[1] && import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  main();
}

